import inspect
import sys

from functools import wraps
from mock import patch as original_patch, DEFAULT
from wrapt import decorator
from six.moves import builtins


def patch(target, object_to_patch, new=DEFAULT, spec=None, create=False,
          spec_set=None, autospec=None, new_callable=None, pass_as_arg=True, **mock_kwargs):
    """A wrapper around mock.patch. The main difference is that rather than strings,
    objects are used for defining what to mock and it is possible to skip passing the mock as an argument.

    New arguments:
    * target is either a class or a module where the patch should be applied (patching happens at module level either way).
    * object_to_patch is the module, class or function that should be replaced with a mock.
    * pass_as_arg is used to control if mock should be passed to the test method. This overrides the default behavior of mock.patch.

    Using patch in with statements does not work yet, but it works as a class and method decorator.

    Examples:
    ::

        @patch(MyTestedClass, os)
        def test_remove_file(self, os_mock):
            MyTestedClass().remove_file('/path/to/file.txt')
            os_mock.unlink.assert_called_once_with('/path/to/file.txt')

        @patch(mytestedmodule, shutil.rmtree, side_effect=OSError, pass_as_arg=False)
        def test_remove_dir_error_propagation(self):
            with self.assertRaises(OSError):
                MyTestedClass().remove_dir('/path/to/dir')

        @patch(mytestedmodule, mytestedmodule.os)  # use this if you don't like importing everything in the test
        def test_something_else(self, os_mock):
            # ...
    """
    patch_path = PatchPathFinder().find(target, object_to_patch)
    mock_kwargs = dict(new=new, spec=spec, create=create, spec_set=spec_set, autospec=autospec, new_callable=new_callable, **mock_kwargs)

    @decorator
    def _wrapper(wrapped, instance, args, kwargs):
        if inspect.isclass(wrapped):
            return _patch_class(wrapped, patch_path, pass_as_arg, mock_kwargs, *args, **kwargs)
        else:
            with original_patch(patch_path, **mock_kwargs) as mock_obj:
                return wrapped(mock_obj, *args, **kwargs) if pass_as_arg else wrapped(*args, **kwargs)
    return _wrapper


def _patch_class(test_class, patch_path, pass_as_arg, mock_kwargs, *args, **kwargs):
    test_instance = test_class(*args, **kwargs)
    for name, test_method in _get_test_methods(test_instance):
        patched_test_method = _patch_method(test_method, patch_path, pass_as_arg, mock_kwargs)
        setattr(test_instance, name, patched_test_method)
    return test_instance


def _get_test_methods(test_instance):
    test_filter = lambda obj: hasattr(obj, '__call__') and hasattr(obj, '__name__') and obj.__name__.startswith('test')
    return inspect.getmembers(test_instance, test_filter)


def _patch_method(test_method, patch_path, pass_as_arg, mock_kwargs):
    @wraps(test_method)
    def _wrapper(*args, **kwargs):
        with original_patch(patch_path, **mock_kwargs) as mock_obj:
            return test_method(mock_obj, *args, **kwargs) if pass_as_arg else test_method(*args, **kwargs)
    return _wrapper


class PatchPathFinder(object):

    def find(self, target, object_to_patch):
        """Returns the path to object_to_patch, as seen by target, in the format required by mock.patch"""
        target_module = self._get_module(target)
        target_name, target_obj = self._find_object_in_target_module(target_module, object_to_patch)
        return self._create_patch_path(target_module, target_name, target_obj, object_to_patch)

    def _get_module(self, module_or_class_or_method):
        if inspect.ismodule(module_or_class_or_method):
            return module_or_class_or_method
        else:
            return sys.modules[module_or_class_or_method.__module__]

    def _find_object_in_target_module(self, target_module, object_to_patch):
        matching_objects = self._find_objects_in_target_module(target_module, object_to_patch)
        if len(matching_objects) == 0:
            raise PatchingError('Could not find a reference to %s in %s' % (object_to_patch, target_module))
        elif len(matching_objects) > 1:
            return self._choose_best_matching_object(matching_objects, object_to_patch)
        else:
            return matching_objects[0]

    def _choose_best_matching_object(self, matching_objects, object_to_patch):
        for name, obj in matching_objects:
            if obj is object_to_patch:
                return name, obj
        for name, obj in matching_objects:
            if self._is_child(object_to_patch, obj):
                return name, obj
        return matching_objects[0]

    def _find_objects_in_target_module(self, target_module, object_to_patch):
        target_members = inspect.getmembers(target_module) + inspect.getmembers(builtins)
        return [(name, member) for name, member in target_members if self._contains(member, object_to_patch)]

    def _contains(self, parent_obj, child_obj):
        if parent_obj == child_obj:
            return True
        elif self._is_child(child_obj, parent_obj):
            return True
        childs_parent_obj = self._get_parent(child_obj)
        if childs_parent_obj is None:
            return False
        else:
            return self._contains(parent_obj, childs_parent_obj)

    def _is_child(self, child_obj, parent_obj):
        return self._get_child_name(child_obj, parent_obj) is not None

    def _get_child_name(self, child_obj, parent_obj):
        members = inspect.getmembers(parent_obj)
        matching_members = [(name, obj) for name, obj in members if child_obj == obj]  # note: 'child_obj is obj' won't work because of bound methods
        if len(matching_members) == 0:
            return None
        elif len(matching_members) > 1:
            return self._choose_best_matching_child(matching_members, child_obj)
        else:
            return matching_members[0][0]

    def _choose_best_matching_child(self, matching_members, child_obj):
        for name, obj in matching_members:
            if name == child_obj.__name__:
                return name
        return matching_members[0][0]

    def _get_parent(self, obj):
        if inspect.ismodule(obj):
            return self._get_module_parent(obj)
        else:
            return sys.modules[obj.__module__]

    def _get_module_parent(self, module):
        name = module.__name__
        if '.' in name:
            parent_name = name.rsplit('.', 1)[0]
            return sys.modules[parent_name]
        else:
            return None

    def _create_patch_path(self, target_module, target_name, target_obj, object_to_patch):
        relative_path = self._get_relative_path(target_obj, object_to_patch)
        if relative_path == '':
            return '.'.join([target_module.__name__, target_name])
        else:
            return '.'.join([target_module.__name__, target_name, relative_path])

    def _get_relative_path(self, base_obj, target_object):
        if base_obj is target_object:
            return ''
        elif self._is_child(target_object, base_obj):
            return self._get_child_name(target_object, base_obj)
        target_parent_object = self._get_parent(target_object)
        if target_parent_object is None:
            raise PatchingError('Cannot calculate relative import path from %s to %s' % (base_obj, target_object))
        target_parent_path = self._get_relative_path(base_obj, target_parent_object)
        name = target_object.__name__
        if target_parent_path == '':
            return name
        else:
            return '.'.join([target_parent_path, name])


class PatchingError(Exception):
    """Raised when a patching is invalid"""
